CREATE TABLE public.demo_sessions (token_hash text primary key, role text not null check(role in ('care-team','caregiver')), expires_at timestamptz not null);
GRANT ALL ON public.demo_sessions TO service_role;
ALTER TABLE public.demo_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.care_profiles (id uuid primary key default gen_random_uuid(), workspace text not null default 'hackathon-demo', baby_name text not null, caregiver_name text not null, plan jsonb not null, created_at timestamptz not null default now());
GRANT ALL ON public.care_profiles TO service_role;
ALTER TABLE public.care_profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.care_appointments (id uuid primary key default gen_random_uuid(), baby_id uuid not null references public.care_profiles(id), starts_at timestamptz not null, reason text not null, status text not null default 'Scheduled' check(status in ('Scheduled','Confirmed','Reschedule requested','Completed','Cancelled')), location jsonb not null default '{}', reschedule jsonb, created_at timestamptz not null default now());
GRANT ALL ON public.care_appointments TO service_role;
ALTER TABLE public.care_appointments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.health_cards (id uuid primary key default gen_random_uuid(), baby_id uuid not null references public.care_profiles(id), category text not null, quote text not null, observation text not null, priority text not null check(priority in ('Routine','Review Needed','Priority Review')), reviewed boolean not null default false, review_note text not null default '', created_at timestamptz not null default now());
GRANT ALL ON public.health_cards TO service_role;
ALTER TABLE public.health_cards ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinical_notes (id uuid primary key default gen_random_uuid(), baby_id uuid not null references public.care_profiles(id), appointment_id uuid not null references public.care_appointments(id), observations text not null, decision text not null, follow_up text not null default '', additional_note text not null default '', created_at timestamptz not null default now());
GRANT ALL ON public.clinical_notes TO service_role;
ALTER TABLE public.clinical_notes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.care_events (id uuid primary key default gen_random_uuid(), baby_id uuid not null references public.care_profiles(id), kind text not null, summary text not null, caregiver_visible boolean not null default true, created_at timestamptz not null default now());
GRANT ALL ON public.care_events TO service_role;
ALTER TABLE public.care_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.care_facility (workspace text primary key, settings jsonb not null default '{}');
GRANT ALL ON public.care_facility TO service_role;
ALTER TABLE public.care_facility ENABLE ROW LEVEL SECURITY;
